// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts Une page de comptes SMPP
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Crée un compte SMPP rattaché à un client
	// (POST /accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// SetPasswordFromAccessLink Définit son mot de passe par un lien à usage unique
	// (POST /auth/access-link)
	SetPasswordFromAccessLink(ctx context.Context, request SetPasswordFromAccessLinkRequestObject) (SetPasswordFromAccessLinkResponseObject, error)
	// Login Premier facteur — adresse et mot de passe
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Fermer la session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Me L'opérateur connecté et ce qu'il a le droit de faire
	// (GET /auth/me)
	Me(ctx context.Context, request MeRequestObject) (MeResponseObject, error)
	// ConfirmTotp Confirmer une application d'authentification en attente, remplaçante ou ajoutée
	// (POST /auth/mfa/totp/confirm)
	ConfirmTotp(ctx context.Context, request ConfirmTotpRequestObject) (ConfirmTotpResponseObject, error)
	// EnrollTotp Enrôler une application d'authentification
	// (POST /auth/mfa/totp/enroll)
	EnrollTotp(ctx context.Context, request EnrollTotpRequestObject) (EnrollTotpResponseObject, error)
	// VerifyMfa Second facteur — code TOTP, code de récupération ou assertion de passkey
	// (POST /auth/mfa/verify)
	VerifyMfa(ctx context.Context, request VerifyMfaRequestObject) (VerifyMfaResponseObject, error)
	// BeginWebauthnAssertion Ouvre une assertion de passkey
	// (POST /auth/mfa/webauthn/assert/begin)
	BeginWebauthnAssertion(ctx context.Context, request BeginWebauthnAssertionRequestObject) (BeginWebauthnAssertionResponseObject, error)
	// ListWebauthnPasskeys Les passkeys de l'opérateur de la session
	// (GET /auth/mfa/webauthn/passkeys)
	ListWebauthnPasskeys(ctx context.Context, request ListWebauthnPasskeysRequestObject) (ListWebauthnPasskeysResponseObject, error)
	// DeleteWebauthnPasskey Retire une passkey
	// (DELETE /auth/mfa/webauthn/passkeys/{passkeyId})
	DeleteWebauthnPasskey(ctx context.Context, request DeleteWebauthnPasskeyRequestObject) (DeleteWebauthnPasskeyResponseObject, error)
	// BeginWebauthnRegistration Ouvre l'enregistrement d'une passkey
	// (POST /auth/mfa/webauthn/register/begin)
	BeginWebauthnRegistration(ctx context.Context, request BeginWebauthnRegistrationRequestObject) (BeginWebauthnRegistrationResponseObject, error)
	// FinishWebauthnRegistration Enregistre la passkey que l'appareil vient de produire
	// (POST /auth/mfa/webauthn/register/finish)
	FinishWebauthnRegistration(ctx context.Context, request FinishWebauthnRegistrationRequestObject) (FinishWebauthnRegistrationResponseObject, error)
	// ListCustomerGroups Les groupes de clients de la passerelle
	// (GET /customer-groups)
	ListCustomerGroups(ctx context.Context, request ListCustomerGroupsRequestObject) (ListCustomerGroupsResponseObject, error)
	// CreateCustomerGroup Crée un groupe de clients
	// (POST /customer-groups)
	CreateCustomerGroup(ctx context.Context, request CreateCustomerGroupRequestObject) (CreateCustomerGroupResponseObject, error)
	// DeleteCustomerGroup Supprime un groupe, sans supprimer aucun client
	// (DELETE /customer-groups/{groupId})
	DeleteCustomerGroup(ctx context.Context, request DeleteCustomerGroupRequestObject) (DeleteCustomerGroupResponseObject, error)
	// GetCustomerGroup Un groupe de clients
	// (GET /customer-groups/{groupId})
	GetCustomerGroup(ctx context.Context, request GetCustomerGroupRequestObject) (GetCustomerGroupResponseObject, error)
	// UpdateCustomerGroup Renomme, décrit, archive ou désarchive un groupe
	// (PATCH /customer-groups/{groupId})
	UpdateCustomerGroup(ctx context.Context, request UpdateCustomerGroupRequestObject) (UpdateCustomerGroupResponseObject, error)
	// ListCustomers Une page de clients de la passerelle
	// (GET /customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// CreateCustomer Crée un client
	// (POST /customers)
	CreateCustomer(ctx context.Context, request CreateCustomerRequestObject) (CreateCustomerResponseObject, error)
	// GetCustomer La fiche d'un client
	// (GET /customers/{customerId})
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// UpdateCustomer Renomme un client
	// (PATCH /customers/{customerId})
	UpdateCustomer(ctx context.Context, request UpdateCustomerRequestObject) (UpdateCustomerResponseObject, error)
	// SetCustomerGroup Affecte un client à un groupe, ou l'en détache
	// (PUT /customers/{customerId}/group)
	SetCustomerGroup(ctx context.Context, request SetCustomerGroupRequestObject) (SetCustomerGroupResponseObject, error)
	// ReactivateCustomer Réactive un client, sans réactiver ses comptes
	// (POST /customers/{customerId}/reactivate)
	ReactivateCustomer(ctx context.Context, request ReactivateCustomerRequestObject) (ReactivateCustomerResponseObject, error)
	// ListSenderIds Les sender IDs d'un client
	// (GET /customers/{customerId}/sender-ids)
	ListSenderIds(ctx context.Context, request ListSenderIdsRequestObject) (ListSenderIdsResponseObject, error)
	// CreateSenderId Enregistre un sender ID
	// (POST /customers/{customerId}/sender-ids)
	CreateSenderId(ctx context.Context, request CreateSenderIdRequestObject) (CreateSenderIdResponseObject, error)
	// DeleteSenderId Supprime un sender ID
	// (DELETE /customers/{customerId}/sender-ids/{senderId})
	DeleteSenderId(ctx context.Context, request DeleteSenderIdRequestObject) (DeleteSenderIdResponseObject, error)
	// UpdateSenderId Approuve ou désactive un sender ID
	// (PATCH /customers/{customerId}/sender-ids/{senderId})
	UpdateSenderId(ctx context.Context, request UpdateSenderIdRequestObject) (UpdateSenderIdResponseObject, error)
	// SuspendCustomer Suspend un client et tous ses comptes
	// (POST /customers/{customerId}/suspend)
	SuspendCustomer(ctx context.Context, request SuspendCustomerRequestObject) (SuspendCustomerResponseObject, error)
	// GetCustomerSuspensionImpact Ce que la suspension d'un client suspendrait avec lui
	// (GET /customers/{customerId}/suspension-impact)
	GetCustomerSuspensionImpact(ctx context.Context, request GetCustomerSuspensionImpactRequestObject) (GetCustomerSuspensionImpactResponseObject, error)
	// Health Sonde de vivacité
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// ListNotifications Les notifications visibles, plus récentes d'abord
	// (GET /notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// MarkNotificationRead Marque une notification lue pour l'opérateur de la session
	// (POST /notifications/{notificationId}/read)
	MarkNotificationRead(ctx context.Context, request MarkNotificationReadRequestObject) (MarkNotificationReadResponseObject, error)
	// ListOperators Les opérateurs, leurs rôles et l'état de leur second facteur
	// (GET /operators)
	ListOperators(ctx context.Context, request ListOperatorsRequestObject) (ListOperatorsResponseObject, error)
	// CreateOperator Crée un opérateur, sans rôle ni mot de passe
	// (POST /operators)
	CreateOperator(ctx context.Context, request CreateOperatorRequestObject) (CreateOperatorResponseObject, error)
	// UpdateOperator Désactive ou réactive un opérateur
	// (PATCH /operators/{operatorId})
	UpdateOperator(ctx context.Context, request UpdateOperatorRequestObject) (UpdateOperatorResponseObject, error)
	// RequestOperatorAccessLink Envoie un lien d'accès à usage unique
	// (POST /operators/{operatorId}/access-link)
	RequestOperatorAccessLink(ctx context.Context, request RequestOperatorAccessLinkRequestObject) (RequestOperatorAccessLinkResponseObject, error)
	// SetOperatorRoles Remplace les rôles d'un opérateur
	// (POST /operators/{operatorId}/roles)
	SetOperatorRoles(ctx context.Context, request SetOperatorRolesRequestObject) (SetOperatorRolesResponseObject, error)
	// ListRoles Les rôles, leurs permissions et leurs détenteurs
	// (GET /roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// CreateRole Compose un rôle personnalisé
	// (POST /roles)
	CreateRole(ctx context.Context, request CreateRoleRequestObject) (CreateRoleResponseObject, error)
	// DeleteRole Supprime un rôle personnalisé que personne ne détient
	// (DELETE /roles/{roleId})
	DeleteRole(ctx context.Context, request DeleteRoleRequestObject) (DeleteRoleResponseObject, error)
	// UpdateRole Remplace la description et les permissions d'un rôle personnalisé
	// (PATCH /roles/{roleId})
	UpdateRole(ctx context.Context, request UpdateRoleRequestObject) (UpdateRoleResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

